package com.commercecore.cart;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface CartRepository extends JpaRepository<Cart,UUID>{Optional<Cart> findByUserId(UUID userId);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from Cart c where c.user.id=:userId")Optional<Cart>findLockedByUserId(@Param("userId")UUID userId);}
